const n = Number(lignes[0]);
const evenements = lignes.slice(1, 1 + n).map(e => e.trim());

let clics = 0;
let compteur = 0;

for (const evenement of evenements) {
  if (evenement === 'click') {
    clics++;
    compteur++;
  } else if (evenement === 'reset') {
    compteur = 0;
  }
}

console.log(clics);
console.log(compteur);

