        this.nom = nom;
        this.age = age;
    }

    String getNom() {
        return nom;
    }

    int getAge() {
        return age;
    }

    void setAge(int age) {
        if (age < 0) {
            throw new IllegalArgumentException("age negatif");
        }
        this.age = age;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String nom = sc.next();
