const actions = (lignes[1] || '').trim().split(' ').filter(Boolean);

for (const act of actions) {
  const [type, rawVal] = act.split(':');
  const val = parseInt(rawVal, 10);
  if (type === 'AJOUT') {
    total += val;
  } else if (type === 'REMISE') {
    total = Math.max(0, total - val);
  }
}
console.log(`Total panier : ${total}`);

