#!/usr/bin/env bash
awk '
function normalize_decimal(value) {
  sub(/^[+]/, "", value)
  sub(/^0+/, "", value)
  return value == "" ? "0" : value
}
function add_decimal(left, right, left_index, right_index, carry, total, result) {
  left_index = length(left)
  right_index = length(right)
  carry = 0
  result = ""
  while (left_index > 0 || right_index > 0 || carry > 0) {
    total = carry
    if (left_index > 0) total += substr(left, left_index--, 1)
    if (right_index > 0) total += substr(right, right_index--, 1)
    result = (total % 10) result
    carry = int(total / 10)
  }
  return result
}
function multiply_decimal(left, right, left_parts, right_parts, product, left_count, right_count, position, start, row, column, carry, total, highest, result) {
  left = normalize_decimal(left)
  right = normalize_decimal(right)
  if (left == "0" || right == "0") return "0"
  left_count = 0
  for (position = length(left); position > 0; position -= 7) {
    start = position - 6
    if (start < 1) start = 1
    left_parts[++left_count] = substr(left, start, position - start + 1) + 0
  }
  right_count = 0
  for (position = length(right); position > 0; position -= 7) {
    start = position - 6
    if (start < 1) start = 1
    right_parts[++right_count] = substr(right, start, position - start + 1) + 0
  }
  for (row = 1; row <= left_count; row++) {
    carry = 0
    for (column = 1; column <= right_count; column++) {
      total = product[row + column - 1] + left_parts[row] * right_parts[column] + carry
      product[row + column - 1] = total % 10000000
      carry = int(total / 10000000)
    }
    product[row + right_count] = carry
  }
  highest = left_count + right_count
  if (product[highest] == 0) highest--
  result = sprintf("%d", product[highest])
  for (position = highest - 1; position > 0; position--) result = result sprintf("%07d", product[position])
  return result
}
NR == 1 { instances = $1; app_disk = $2; app_ram = $3 }
NR == 2 {
  docker_disk = multiply_decimal(instances, app_disk)
  docker_ram = multiply_decimal(instances, app_ram)
  guest_disk = multiply_decimal(instances, $1)
  guest_ram = multiply_decimal(instances, $2)
  vm_disk = add_decimal(docker_disk, guest_disk)
  vm_ram = add_decimal(docker_ram, guest_ram)
  printf "ARCHITECTURE VM: Disque %s Mo | RAM %s Mo\n", vm_disk, vm_ram
  printf "ARCHITECTURE DOCKER: Disque %s Mo | RAM %s Mo\n", docker_disk, docker_ram
  printf "ECONOMIE DOCKER: Disque -%s Mo | RAM -%s Mo\n", guest_disk, guest_ram
}
'

