  instruction = trim(instruction)
  count = split(instruction, fields, /[[:space:]]+/)
  command = toupper(fields[1])
  if (!first_seen) {
    first_seen = 1
    if (command != "FROM" && command != "ARG") invalid = 1
  }
  if (command == "FROM") from_seen = 1
  if (command == "ADD") {
