      if (fields[index_field] !~ /^https?:\/\// && tolower(fields[index_field]) !~ /\.(tar|gz|zip)$/) local_file = 1
    }
    if (local_file) warnings[++warning_count] = sprintf("AVERTISSEMENT [Ligne %d]: Preferer COPY a ADD pour les fichiers locaux", number)
  }
  if (command == "RUN") {
    body = substr(instruction, length(fields[1]) + 1)
    if (body ~ /apt-get[[:space:]]+update/ && body !~ /apt-get[[:space:]]+install/)
      warnings[++warning_count] = sprintf("AVERTISSEMENT [Ligne %d]: RUN apt-get update isole (fusionner avec install et rm -rf /var/lib/apt/lists/*)", number)
  }
}
{
