    def __init__(self, val):
        self.val = val
        self.g = None
        self.d = None

def insert(root, val):
    if root is None:
        return Node(val)
    if val < root.val:
        root.g = insert(root.g, val)
    elif val > root.val:
        root.d = insert(root.d, val)
    return root

def search(root, val):
    cur = root
    comps = 0
    depth = 0
    last_depth = 0
    while cur is not None:
        comps += 1
        last_depth = depth
        if cur.val == val:
            return True, comps, depth
        elif val < cur.val:
            cur = cur.g
            depth += 1
        else:
            cur = cur.d
            depth += 1
    return False, comps, last_depth

