import sys
import re

lignes = [l.strip() for l in sys.stdin.read().splitlines() if l.strip()]

class Node:
    def __init__(self, val):
        self.val = val
        self.g = None
        self.d = None

def insert(root, val):
    if root is None:
        return Node(val)
    if val < root.val:
        root.g = insert(root.g, val)
    elif val > root.val:
        root.d = insert(root.d, val)
    return root

def find_node(root, val):
    cur = root
    while cur:
        if cur.val == val:
            return cur
        elif val < cur.val:
            cur = cur.g
        else:
            cur = cur.d
    return None

def min_value_node(node):
    cur = node
    while cur.g is not None:
        cur = cur.g
    return cur

def delete_node(root, val):
    if root is None:
        return root
    if val < root.val:
        root.g = delete_node(root.g, val)
    elif val > root.val:
        root.d = delete_node(root.d, val)
    else:
        if root.g is None:
            return root.d
        elif root.d is None:
            return root.g
        temp = min_value_node(root.d)
        root.val = temp.val
        root.d = delete_node(root.d, temp.val)
    return root

def get_infixe(root):
    res = []
    def rec(n):
        if n:
            rec(n.g)
            res.append(n.val)
            rec(n.d)
    rec(root)
    return res

for lig in lignes:
    m = re.search(r'nom=([^\s]+).*?CLES=([^\s]+).*?CIBLE=(\d+)', lig)
    if not m:
        continue
    nom = m.group(1)
    cles = [int(x) for x in m.group(2).split(',') if x]
    cible = int(m.group(3))

    root = None
    for c in cles:
        root = insert(root, c)

    target = find_node(root, cible)
    if target is None:
        cas = "ABSENT"
    elif target.g is None and target.d is None:
        cas = "FEUILLE"
    elif target.g is not None and target.d is not None:
        cas = "DEUX_ENFANTS"
    else:
        cas = "UN_ENFANT"

    if cas != "ABSENT":
        root = delete_node(root, cible)

    inf = get_infixe(root)
    inf_str = ", ".join(str(x) for x in inf) if inf else "VIDE"
    print(f"SUPPR: nom={nom} | CIBLE: {cible} | CAS: {cas} | INFIXE_APRES: {inf_str}")

import sys
import re

lignes = [l.strip() for l in sys.stdin.read().splitlines() if l.strip()]

class UnionFind:
    def __init__(self, items):
        self.parent = {x: x for x in items}
        self.rank = {x: 0 for x in items}

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        rx = self.find(x)
        ry = self.find(y)
        if rx == ry:
            return False
        if self.rank[rx] < self.rank[ry]:
            self.parent[rx] = ry
        elif self.rank[rx] > self.rank[ry]:
            self.parent[ry] = rx
        else:
            self.parent[ry] = rx
            self.rank[rx] += 1
        return True

for lig in lignes:
    m = re.search(r'nom=([^\s]+).*?SOMMETS=([^\s]+).*?ARETES=(.*)', lig)
    if not m:
        continue
    nom = m.group(1)
    sommets = [s.strip() for s in m.group(2).split(',') if s.strip()]
    aretes_str = m.group(3).strip()
    aretes_raw = [a.strip() for a in aretes_str.split(',') if a.strip()]

    parsed_edges = []
    for a in aretes_raw:
        m_e = re.match(r'([^-]+)-([^:]+):(-?\d+)', a)
        if m_e:
            u, v = m_e.group(1).strip(), m_e.group(2).strip()
            w = int(m_e.group(3))
            if u > v:
                u, v = v, u
            parsed_edges.append((w, u, v))

    # Tri par poids croissant, puis ordre lexicographique
    parsed_edges.sort(key=lambda x: (x[0], x[1], x[2]))

    uf = UnionFind(sommets)
    mst = []
    total_weight = 0
    rejets = 0

    for w, u, v in parsed_edges:
        if uf.union(u, v):
            mst.append(f"{u}-{v}:{w}")
            total_weight += w
        else:
            rejets += 1

    mst_str = ", ".join(mst)
    print(f"KRUSKAL: nom={nom} | POIDS_MST: {total_weight} | ARETES: {mst_str} | REJETS: {rejets}")

